import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function designed to mimic characteristics of quadratic landscapes
    with some added non-linearity. It combines a quadratic bowl with a tilted
    ellipsoid and a simple cosine wave.

    Formula:
    f(x) = quadratic_bowl(x) + ellipsoid(x) + wave(x)

    where:
    - quadratic_bowl(x) = sum(x_i^2)
    - ellipsoid(x) = sum(i * x_i^2), where i is the index of x_i
    - wave(x) = cos(sum(x_i))
    """

    def quadratic_bowl(x):
        return np.sum(x**2)

    def ellipsoid(x):
        indices = np.arange(1, len(x) + 1)
        return np.sum(indices * x**2)

    def wave(x):
        return np.cos(np.sum(x))


    return quadratic_bowl(x) * 0.5 + ellipsoid(x) * 0.1 + wave(x) * 0.75

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a modified Rosenbrock, a modified Rastrigin, a linear term, and a shifted damped quadratic term.

    Formula:
    f(x) = 0.3 * Rosenbrock(x) + 0.4 * Rastrigin(x) + 0.1 * sum(x)  + 0.2 * DampedShiftedQuadratic(x)
    """

    def Rosenbrock(x):
        """Modified Rosenbrock function (sum of squares of differences)."""
        return np.sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0)

    def Rastrigin(x):
        """Modified Rastrigin function."""
        n = len(x)
        return 10 * n + np.sum(x**2 - 10 * np.cos(2 * np.pi * x))

    def DampedShiftedQuadratic(x):
        """Damped and Shifted Quadratic: sum (i * (x_i - shift_i)^2 ) * exp( - ||x - shift||^2)"""
        shift = np.array([0.1, -0.2]) if len(x) == 2 else np.zeros(len(x))
        return np.sum(np.arange(1, len(x) + 1) * (x - shift)**2) * np.exp(-np.sum((x - shift)**2))

    return 0.3 * Rosenbrock(x) + 0.4 * Rastrigin(x) + 0.1 * np.sum(x) + 0.2 * DampedShiftedQuadratic(x)
